import{_ as a,o as r,c as t,a3 as o}from"./chunks/framework.D3oaa6bG.js";const h=JSON.parse('{"title":"PDF","description":"","frontmatter":{},"headers":[],"relativePath":"development/core/pdf.md","filePath":"development/core/pdf.md","lastUpdated":null}'),n={name:"development/core/pdf.md"};function l(i,e,d,p,f,s){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="pdf" tabindex="-1">PDF <a class="header-anchor" href="#pdf" aria-label="Permalink to &quot;PDF&quot;">​</a></h1><p>Mall bundles the great <a href="https://github.com/barryvdh/laravel-dompdf/" target="_blank" rel="noreferrer">barryvdh/laravel-dompdf</a> to generate PDF files.</p><p>Refer to it&#39;s <a href="https://github.com/barryvdh/laravel-dompdf/blob/master/readme.md" target="_blank" rel="noreferrer">README</a> for usage details.</p><h2 id="pdfmaker-trait" tabindex="-1">PDFMaker Trait <a class="header-anchor" href="#pdfmaker-trait" aria-label="Permalink to &quot;PDFMaker Trait&quot;">​</a></h2><p>Mall provides a <a href="https://github.com/wintercms/wn-mall-plugin/blob/develop/classes/traits/PDFMaker.php" target="_blank" rel="noreferrer"><code>PDFMaker</code></a> trait that can be used to generate PDF files.</p><p>Currently, the <code>Order</code> and <code>Wishlist</code> models implement it by default.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>Mall exposes all of the original <a href="https://github.com/wintercms/wn-mall-plugin/blob/develop/config/pdf.php" target="_blank" rel="noreferrer"><code>barryvdh/laravel-dompdf</code> config entries</a> in a separate configuration file.</p><p>If you wish to change the default PDF configuration create a <code>config/offline/mall/pdf.php</code> file and return your custom config.</p><p>See <a href="https://wintercms.com/docs/plugin/settings#file-configuration" target="_blank" rel="noreferrer">October&#39;s docs on overriding configuration</a>.</p>',10)])])}const m=a(n,[["render",l]]);export{h as __pageData,m as default};
